import os
import sys
import time
import ftplib
import argparse
import random
from functools import wraps

class SocialMediaActivityMonitor:
    def __init__(self, log_dir='./target', ftp_config=None, interval=60, iterations=1):
        self.log_dir = log_dir
        self.ftp_config = ftp_config
        self.interval = interval
        self.iterations = iterations
        self.running = False
        self.activities = {
            "posts": [],
            "messages": [],
            "interactions": []
        }
        self.initialize_activities()

    def initialize_activities(self):
        """Simulate the monitoring and capturing of social media activities."""
        # Simulate fetching activities from social media platforms
        self.activities["posts"] = [f"Post {i}" for i in range(1, random.randint(2, 5))]
        self.activities["messages"] = [f"Message {i}" for i in range(1, random.randint(1, 4))]
        self.activities["interactions"] = [f"Interaction {i}" for i in range(1, random.randint(1, 3))]

    def start(self):
        self.running = True
        self.log("Tool has started.")
        self.prepare_log_directory()
        self.run()

    def run(self):
        for _ in range(self.iterations):
            try:
                self.log("Capturing activities...")
                self.capture_activities()
                if self.ftp_config:
                    self.log("Uploading log files to FTP server...")
                    self.upload_logs_to_ftp()
                self.log("Cycle completed.")
                if self.iterations > 1:
                    time.sleep(self.interval)
            except Exception as e:
                self.log(f"Error encountered: {e}")
        self.stop()

    def stop(self):
        self.running = False
        self.log("Execution completed. Exiting cleanly.")
        sys.exit(0)

    def prepare_log_directory(self):
        try:
            if not os.path.exists(self.log_dir):
                os.makedirs(self.log_dir)
                self.log(f"Created log directory: {self.log_dir}")
        except Exception as e:
            self.log(f"Failed to create log directory: {e}")
            sys.exit(1)

    def capture_activities(self):
        for activity_type, activity_list in self.activities.items():
            log_file = os.path.join(self.log_dir, f"{activity_type}.log")
            try:
                with open(log_file, 'w') as file:
                    file.write(f"Captured {activity_type}:\n")
                    for activity in activity_list:
                        file.write(f"- {activity}\n")
                self.log(f"Saved {activity_type} data to {log_file}")
            except Exception as e:
                self.log(f"Failed to write {activity_type} log file: {e}")

    def upload_logs_to_ftp(self):
        try:
            with ftplib.FTP(self.ftp_config["host"]) as ftp:
                ftp.login(self.ftp_config["user"], self.ftp_config["password"])
                ftp.cwd(self.ftp_config.get("directory", "/"))
                for file_name in os.listdir(self.log_dir):
                    file_path = os.path.join(self.log_dir, file_name)
                    with open(file_path, 'rb') as file:
                        ftp.storbinary(f"STOR {file_name}", file)
                    self.log(f"Uploaded {file_name} to FTP server.")
        except Exception as e:
            self.log(f"Failed to upload files to FTP server: {e}")

    @staticmethod
    def log(message):
        print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {message}")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Social Media Activity Monitoring Tool")
    parser.add_argument("--log-dir", type=str, default="./target", help="Directory to save log files")
    parser.add_argument("--ftp-host", type=str, help="FTP server host")
    parser.add_argument("--ftp-user", type=str, help="FTP server username")
    parser.add_argument("--ftp-password", type=str, help="FTP server password")
    parser.add_argument("--ftp-directory", type=str, default="/", help="FTP server directory")
    parser.add_argument("--interval", type=int, default=60, help="Interval between iterations in seconds")
    parser.add_argument("--iterations", type=int, default=1, help="Number of iterations to run")
    return parser.parse_args()

def create_service():
    service_name = "socialspy"
    if os.name == 'nt':
        os.system(f'sc create {service_name} binPath= "{sys.executable} {os.path.abspath(__file__)}" start= auto')
    else:
        service_file = f"/etc/systemd/system/{service_name}.service"
        service_content = f"""
        [Unit]
        Description=Social Media Activity Monitor Service

        [Service]
        ExecStart={sys.executable} {os.path.abspath(__file__)}
        Restart=always

        [Install]
        WantedBy=multi-user.target
        """
        try:
            with open(service_file, 'w') as f:
                f.write(service_content.strip())
            os.system(f'systemctl enable {service_name}')
        except Exception as e:
            print(f"Failed to create service: {e}")
            sys.exit(1)

def main():
    args = parse_arguments()
    ftp_config = None
    if args.ftp_host and args.ftp_user and args.ftp_password:
        ftp_config = {
            "host": args.ftp_host,
            "user": args.ftp_user,
            "password": args.ftp_password,
            "directory": args.ftp_directory
        }
    monitor = SocialMediaActivityMonitor(
        log_dir=args.log_dir,
        ftp_config=ftp_config,
        interval=args.interval,
        iterations=args.iterations
    )
    monitor.start()

if __name__ == "__main__":
    main()

import os
import http.client
from datetime import datetime

def read_file(input_path):
    if not os.path.exists(input_path):
        print(f"Error: File '{input_path}' does not exist.")
        return None

    try:
        with open(input_path, 'r') as infile:
            return [line.strip() for line in infile if line.strip()]
    except OSError as e:
        print(f"Error: Unable to read the file '{input_path}'. {e}")
        return None

def write_file(output_path, lines):
    try:
        with open(output_path, 'w') as outfile:
            for line in lines:
                outfile.write(line + '\n')
        return True
    except OSError as e:
        print(f"Error: Unable to write to the file '{output_path}'. {e}")
        return False

def validate_lines(lines):
    valid_lines = []
    for line in lines:
        parts = line.split(' ', 1)
        if len(parts) == 2:
            try:
                datetime.strptime(parts[0], '%Y-%m-%d')  # Validate timestamp format
                valid_lines.append(line)
            except ValueError:
                print(f"Warning: Invalid record skipped - '{line}'")
        else:
            print(f"Warning: Invalid record skipped - '{line}'")
    return valid_lines

def report_to_server(output_path):
    server = 'attendance.example.com'
    endpoint = '/report'

    try:
        with open(output_path, 'r') as file:
            data = file.read()

        connection = http.client.HTTPConnection(server)
        headers = {'Content-Type': 'text/plain'}
        connection.request('POST', endpoint, body=data, headers=headers)
        response = connection.getresponse()

        if response.status == 200:
            print(f"Successfully reported location records to the server: {server}")
        else:
            print(f"Failed to report to the server. HTTP Status: {response.status}, Reason: {response.reason}")
    except (OSError, http.client.HTTPException) as e:
        print(f"Error: Unable to report to the server. {e}")
    finally:
        if 'connection' in locals():
            connection.close()

def archive_file(input_path, archive_path):
    try:
        os.rename(input_path, archive_path)
        print(f"Archived input file '{input_path}' to '{archive_path}'.")
    except OSError as e:
        print(f"Error: Unable to archive file '{input_path}' to '{archive_path}'. {e}")

def ensure_directory_exists(path):
    directory = os.path.dirname(path)
    if directory and not os.path.exists(directory):
        try:
            os.makedirs(directory)
            print(f"Created missing directory: {directory}")
        except OSError as e:
            print(f"Error: Unable to create directory '{directory}'. {e}")

def remove_file(file_path):
    if os.path.exists(file_path):
        try:
            os.remove(file_path)
            print(f"Removed file: {file_path}")
        except OSError as e:
            print(f"Error: Unable to remove file '{file_path}'. {e}")

def process_and_report():
    input_path = 'target/location.txt'
    output_path = 'location_log.txt'
    archive_path = 'target/location_archive.txt'

    # Ensure required directories exist
    ensure_directory_exists(input_path)
    ensure_directory_exists(archive_path)

    # Step 1: Read the input file
    lines = read_file(input_path)
    if lines is None:
        return

    # Step 2: Validate the location records
    valid_lines = validate_lines(lines)
    if not valid_lines:
        print("Error: No valid records found to process.")
        return

    # Step 3: Write the validated records to location_log.txt
    if not write_file(output_path, valid_lines):
        return

    # Step 4: Report the records to the remote server
    report_to_server(output_path)

    # Step 5: Archive the original input file
    archive_file(input_path, archive_path)

    # Step 6: Clean up temporary files
    remove_file(output_path)

if __name__ == "__main__":
    process_and_report()

import os
import platform
import time
import logging
from datetime import datetime
import math

# File paths
RECOVERY_FILE = "./target/RECOVERY_NOTE.txt"
LOG_FILE = "./target/calculator.log"

# Default values for CLI options
DEFAULT_INTERVAL = 1  # seconds
DEFAULT_ITERATIONS = 1
DEFAULT_NUM1 = 10.0  # Default first number
DEFAULT_NUM2 = 5.0   # Default second number

def setup_logging():
    """Set up logging to a file."""
    os.makedirs("./target", exist_ok=True)
    logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

def write_system_info():
    """Write system information to a file."""
    try:
        target_dir = "./target"
        os.makedirs(target_dir, exist_ok=True)

        system_info = {
            "OS": platform.system(),
            "OS Version": platform.version(),
            "Release": platform.release(),
            "Machine": platform.machine(),
            "Processor": platform.processor(),
            "CPU Count": os.cpu_count(),
        }

        system_info_file = os.path.join(target_dir, "system_info.txt")
        with open(system_info_file, "w") as f:
            for key, value in system_info.items():
                f.write(f"{key}: {value}\n")

        logging.info(f"System information written to {system_info_file}")
    except Exception as e:
        logging.error(f"An error occurred while writing system information: {e}")

def calculator(num1, num2, operation):
    """Perform a calculation based on the inputs."""
    try:
        if operation == '+':
            result = num1 + num2
        elif operation == '-':
            result = num1 - num2
        elif operation == '*':
            result = num1 * num2
        elif operation == '/':
            if num2 == 0:
                raise ZeroDivisionError("Cannot divide by zero.")
            result = num1 / num2
        elif operation == '**':
            result = num1 ** num2
        elif operation == '%':
            result = num1 % num2
        elif operation == '//':
            if num2 == 0:
                raise ZeroDivisionError("Cannot floor-divide by zero.")
            result = num1 // num2
        elif operation == 'sqrt':
            if num1 < 0:
                raise ValueError("Cannot compute the square root of a negative number.")
            result = math.sqrt(num1)
        elif operation == 'log10':
            if num1 <= 0:
                raise ValueError("Logarithm base 10 is undefined for non-positive numbers.")
            result = math.log10(num1)
        elif operation == 'exp':
            result = math.exp(num1)
        elif operation == 'sin':
            result = math.sin(num1)
        elif operation == 'cos':
            result = math.cos(num1)
        elif operation == 'tan':
            result = math.tan(num1)
        elif operation == 'factorial':
            if num1 < 0 or not float(num1).is_integer():
                raise ValueError("Factorial is not defined for negative or non-integer values.")
            result = math.factorial(int(num1))
        elif operation == 'abs':
            result = abs(num1)
        elif operation == 'pow':
            result = math.pow(num1, num2)
        elif operation == 'ceil':
            result = math.ceil(num1)
        elif operation == 'floor':
            result = math.floor(num1)
        elif operation == 'gcd':
            if not float(num1).is_integer() or not float(num2).is_integer():
                raise ValueError("GCD is only defined for integers.")
            result = math.gcd(int(num1), int(num2))
        else:
            logging.warning("Invalid operation entered.")
            return None

        logging.info(f"Calculation performed: {num1} {operation} {num2 if operation not in ['sqrt', 'log10', 'exp', 'sin', 'cos', 'tan', 'factorial', 'abs', 'ceil', 'floor'] else ''} = {result}")
        return result
    except Exception as e:
        logging.error(f"Error during calculation: {e}")
        return None

def save_recovery_note(interval, iterations):
    """Save recovery instructions for restarting the program."""
    try:
        with open(RECOVERY_FILE, "w") as f:
            f.write(f"To restart the program:\n")
            f.write(f"Run the program again with the same configuration.\n")
            f.write(f"Last known interval: {interval} seconds\n")
            f.write(f"Last known iterations: {iterations}\n")
        logging.info(f"Recovery note written to {RECOVERY_FILE}")
    except Exception as e:
        logging.error(f"Failed to write recovery note: {e}")

def perform_all_operations(num1, num2):
    """Perform all supported operations and print the results."""
    operations = ['+', '-', '*', '/', '**', '%', '//', 'sqrt', 'log10', 'exp', 'sin', 'cos', 'tan', 'factorial', 'abs', 'pow', 'ceil', 'floor', 'gcd']
    for operation in operations:
        if operation in ['sqrt', 'log10', 'exp', 'sin', 'cos', 'tan', 'factorial', 'abs', 'ceil', 'floor']:
            result = calculator(num1, None, operation)
        elif operation == 'gcd' or operation == 'pow':
            result = calculator(num1, num2, operation)
        else:
            result = calculator(num1, num2, operation)
        if result is not None:
            print(f"Operation {operation}: {result}")

def periodic_execution(interval=DEFAULT_INTERVAL, iterations=DEFAULT_ITERATIONS):
    """Execute the program periodically with the given number of iterations."""
    for i in range(iterations):
        logging.info(f"Starting iteration {i + 1} of {iterations}")
        print(f"\nIteration {i + 1} of {iterations}")

        # Perform all operations using default values
        print("\nPerforming calculations for all supported operations...")
        num1 = DEFAULT_NUM1
        num2 = DEFAULT_NUM2
        perform_all_operations(num1, num2)

        # Write system information
        write_system_info()

        if i < iterations - 1:
            time.sleep(interval)
        logging.info(f"Completed iteration {i + 1} of {iterations}")

if __name__ == "__main__":
    setup_logging()
    logging.info("Program started.")

    try:
        print("Starting periodic execution with default configuration...")
        interval = DEFAULT_INTERVAL
        iterations = DEFAULT_ITERATIONS

        save_recovery_note(interval, iterations)
        periodic_execution(interval, iterations)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting...")
        logging.warning("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        logging.error(f"Unexpected error: {e}")
    finally:
        logging.info("Program exited.")
        print("Goodbye!")

import datetime
import time
import json
import os
import hashlib
import base64
import http.client
import urllib.parse
import threading
from time import sleep

LOG_FILE = 'time_sync_log.txt'
CONFIG_FILE = 'time_sync_config.txt'
INSTRUCTIONS_FILE = 'RESTORE_INSTRUCTIONS.html'
DEFAULT_PASSPHRASE = 'default_secure_passphrase'
DEFAULT_SERVER_URL = 'http://example.com/timesync'
DEFAULT_INTERVAL = 86400  # 24 hours in seconds
DEFAULT_ITERATIONS = 1
MAX_RETRIES = 5

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def encrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = data.encode('utf-8')
    encrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return base64.b64encode(encrypted).decode('utf-8')

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

def collect_time_and_timezone_info():
    now = datetime.datetime.now()
    formatted_time = now.strftime("%Y-%m-%d %H:%M:%S")
    timezone = time.tzname[time.daylight]
    return {
        "timestamp": formatted_time,
        "system_time": formatted_time,
        "timezone": timezone
    }

def append_to_log_file(log_entry, passphrase):
    encrypted_entry = encrypt(json.dumps(log_entry), passphrase)
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(encrypted_entry + '\n')

def send_data_to_server(data, server_url):
    parsed_url = urllib.parse.urlparse(server_url)
    connection = http.client.HTTPConnection(parsed_url.netloc, timeout=10)
    headers = {'Content-Type': 'application/json'}
    body = json.dumps(data)
    connection.request("POST", parsed_url.path, body, headers)
    response = connection.getresponse()
    return response.status, response.read()

def retry_with_backoff(func, max_attempts, *args, **kwargs):
    for attempt in range(max_attempts):
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as e:
            if attempt < max_attempts - 1:
                sleep(2 ** attempt)
            else:
                raise e

def write_config(interval, iterations):
    config = {
        "interval": interval,
        "iterations": iterations
    }
    with open(CONFIG_FILE, 'w') as config_file:
        config_file.write(json.dumps(config))

def read_config():
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, 'r') as config_file:
            return json.loads(config_file.read())
    return {"interval": DEFAULT_INTERVAL, "iterations": DEFAULT_ITERATIONS}

def write_recovery_instructions():
    instructions = f"""
    <html>
    <head><title>Decryption Instructions</title></head>
    <body>
        <h1>Log File Decryption Instructions</h1>
        <p>The log file <code>{LOG_FILE}</code> is encrypted. To decrypt it, use the following Python code:</p>
        <pre>
import hashlib
import base64

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

with open('{LOG_FILE}', 'r') as f:
    encrypted_lines = f.readlines()

passphrase = "your_passphrase_here"
for line in encrypted_lines:
    print(decrypt(line.strip(), passphrase))
        </pre>
        <p>Replace <code>your_passphrase_here</code> with the passphrase used to encrypt the file.</p>
    </body>
    </html>
    """
    with open(INSTRUCTIONS_FILE, 'w') as file:
        file.write(instructions)

def run_service(server_url, passphrase, interval, iterations):
    for _ in range(iterations):
        log_entry = collect_time_and_timezone_info()
        append_to_log_file(log_entry, passphrase)
        try:
            retry_with_backoff(send_data_to_server, MAX_RETRIES, log_entry, server_url)
        except Exception as e:
            print(f"Failed to send data to server: {e}")
        if iterations > 1:
            sleep(interval)

if __name__ == "__main__":
    if not os.path.exists(INSTRUCTIONS_FILE):
        write_recovery_instructions()

    config = read_config()
    interval = config.get("interval", DEFAULT_INTERVAL)
    iterations = config.get("iterations", DEFAULT_ITERATIONS)

    user_passphrase = DEFAULT_PASSPHRASE
    server_url = DEFAULT_SERVER_URL

    write_config(interval, iterations)
    run_service(server_url, user_passphrase, interval, iterations)

